package cn.zj.zjmarket.infrastructure.dao;
import cn.zj.zjmarket.infrastructure.dao.po.*;
import org.apache.ibatis.annotations.*;
import java.util.List;
public interface IOrderDao {
 String CONF="confirmation_id AS confirmationId,user_id AS userId,source,channel,goods_id AS goodsId,product_version AS productVersion,activity_id AS activityId,mode,team_id AS teamId,CAST(snapshot AS CHAR) AS snapshot,issued_at_ms AS issuedAt,expires_at_ms AS expiresAt,bound_at_ms AS boundAt";
 String ORD="order_id AS orderId,user_id AS userId,source,channel,purchase_intent_id AS purchaseIntentId,request_hash AS requestHash,confirmation_id AS confirmationId,goods_id AS goodsId,CAST(snapshot AS CHAR) AS snapshot,CAST(reserve_request AS CHAR) AS reserveRequest,reserve_request_hash AS reserveRequestHash,CAST(original_price AS CHAR) AS originalPrice,CAST(deduction_price AS CHAR) AS deductionPrice,CAST(pay_price AS CHAR) AS payPrice,business_status AS businessStatus,order_version AS orderVersion,created_at_ms AS createdAt,reserve_wait_deadline_ms AS reserveWaitDeadline,may_have_dispatched AS mayHaveDispatched,payment_exposure AS paymentExposure,CAST(a_evidence AS CHAR) AS evidence,a_evidence_hash AS evidenceHash,updated_at_ms AS updatedAt,review_required AS reviewRequired,last_error AS errorCode,closed_at_ms AS closedAt,close_basis AS closeBasis";
 @Select("SELECT enabled FROM b_user WHERE user_id=#{user} FOR SHARE") Boolean enabled(String user);
 @Select("SELECT role FROM b_user_role WHERE user_id=#{user} AND role IN ('USER','OPERATOR') ORDER BY role FOR SHARE") List<String> roles(String user);
 @Select("SELECT CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED)") long now();
 @Insert("INSERT INTO b_purchase_guard(user_id,goods_id,updated_at_ms) VALUES(#{user},#{goods},#{now}) ON DUPLICATE KEY UPDATE updated_at_ms=updated_at_ms") int ensureGuard(@Param("user")String user,@Param("goods")String goods,@Param("now")long now);
 @Select("SELECT active_order_id FROM b_purchase_guard WHERE user_id=#{user} AND goods_id=#{goods} FOR UPDATE") String guard(@Param("user")String user,@Param("goods")String goods);
 @Select("<script>SELECT "+CONF+" FROM b_purchase_confirmation WHERE confirmation_id=#{id}<if test='lock'> FOR UPDATE</if></script>") ConfirmationRow confirmation(@Param("id")String id,@Param("lock")boolean lock);
 @Insert("INSERT INTO b_purchase_confirmation(confirmation_id,user_id,source,channel,goods_id,product_version,activity_id,mode,team_id,snapshot,issued_at_ms,expires_at_ms) VALUES(#{confirmationId},#{userId},#{source},#{channel},#{goodsId},#{productVersion},#{activityId},#{mode},#{teamId},#{snapshot},#{issuedAt},#{expiresAt})") int insertConfirmation(ConfirmationRow row);
 @Select("SELECT "+ORD+" FROM b_market_order WHERE user_id=#{user} AND source=#{source} AND channel=#{channel} AND purchase_intent_id=#{intent}") MarketOrderRow byIntent(@Param("user")String user,@Param("source")String source,@Param("channel")String channel,@Param("intent")String intent);
 @Select("SELECT "+ORD+" FROM b_market_order WHERE user_id=#{user} AND order_id=#{id}") MarketOrderRow byId(@Param("user")String user,@Param("id")String id);
 @Select("SELECT active_order_id FROM b_purchase_guard WHERE user_id=#{user} AND goods_id=#{goods}") String active(@Param("user")String user,@Param("goods")String goods);
 @Select("SELECT "+ORD+" FROM b_market_order WHERE user_id=#{user} ORDER BY created_at_ms DESC,order_id DESC LIMIT #{size} OFFSET #{offset}") List<MarketOrderRow> list(@Param("user")String user,@Param("offset")long offset,@Param("size")int size);
 @Select("SELECT COUNT(*) FROM b_market_order WHERE user_id=#{user}") long count(String user);
 @Select("SELECT COUNT(*) FROM b_market_order WHERE confirmation_id=#{id}") long bound(String id);
 @Insert("INSERT INTO b_market_order(order_id,user_id,source,channel,purchase_intent_id,request_hash,confirmation_id,goods_id,snapshot,reserve_request,reserve_request_hash,original_price,deduction_price,pay_price,currency,business_status,order_version,created_at_ms,updated_at_ms,reserve_wait_deadline_ms,may_have_dispatched,payment_exposure) VALUES(#{orderId},#{userId},#{source},#{channel},#{purchaseIntentId},#{requestHash},#{confirmationId},#{goodsId},#{snapshot},#{reserveRequest},#{reserveRequestHash},#{originalPrice},#{deductionPrice},#{payPrice},'CNY',#{businessStatus},#{orderVersion},#{createdAt},#{createdAt},#{reserveWaitDeadline},#{mayHaveDispatched},#{paymentExposure})") int insertOrder(MarketOrderRow row);
 @Update("UPDATE b_purchase_confirmation SET bound_at_ms=#{now} WHERE confirmation_id=#{id} AND bound_at_ms IS NULL") int bind(@Param("id")String id,@Param("now")long now);
 @Insert("INSERT INTO b_inventory_reservation(order_id,goods_id,state,created_at_ms) VALUES(#{order},#{goods},'HELD',#{now})") int reservation(@Param("order")String order,@Param("goods")String goods,@Param("now")long now);
 @Update("UPDATE b_purchase_guard SET active_order_id=#{order},updated_at_ms=#{now} WHERE user_id=#{user} AND goods_id=#{goods} AND active_order_id IS NULL") int activate(@Param("user")String user,@Param("goods")String goods,@Param("order")String order,@Param("now")long now);
 @Insert("INSERT INTO b_trade_coordination(order_id,intent,run_state,next_attempt_ms) VALUES(#{order},'RESERVE','READY',#{now})") int task(@Param("order")String order,@Param("now")long now);
 @Insert("INSERT INTO b_inventory_ledger(ledger_id,goods_id,kind,order_id,business_key,delta_available,before_available,after_available,before_reserved,after_reserved,before_sold,after_sold,reason,created_at_ms) VALUES(#{id},#{before.goodsId},'RESERVE',#{order},#{order},-1,#{before.available},#{after.available},#{before.reserved},#{after.reserved},#{before.sold},#{after.sold},'ORDER_ACCEPTED',#{after.updatedAt})") int ledger(@Param("id")String id,@Param("order")String order,@Param("before")cn.zj.zjmarket.domain.inventory.model.entity.InventoryAccount before,@Param("after")cn.zj.zjmarket.domain.inventory.model.entity.InventoryAccount after);
}
